fn profile_offers_of(v: &Value) -> PalwGenProfileOffersV1 {
    match v["kind"].as_str().unwrap() {
        "none" => PalwGenProfileOffersV1::None,
        "image" => PalwGenProfileOffersV1::Image(PalwGenImageOffersV1 {
            sampler_id: Hash64::from_bytes(h64v(&v["sampler_id_hex"])),
            guidance: v["guidance"].as_object().map(|_| PalwGenGuidanceOfferV1 {
                scalar: v["guidance"]["scalar"].as_u64().unwrap() as u8,
                lo: v["guidance"]["lo"].as_u64().unwrap() as u16,
                hi: v["guidance"]["hi"].as_u64().unwrap() as u16,
            }),
            steps_scalar: v["steps_scalar"].as_u64().map(|x| x as u8),
        }),
        "embedding" => PalwGenProfileOffersV1::Embedding(PalwGenEmbeddingOffersV1 {
            pooling: v["pooling"].as_u64().unwrap() as u8,
            dims: u32s(&v["dims"]),
        }),
        k => panic!("profile offers kind {k}"),
    }
}

/// The class a vector entry states, rebuilt from its fields and the source vector's program bytes, with its
/// artifact root.
fn class_of(entry: &Value) -> (PalwGenClassV1, Hash64) {
    let source = load(entry["source"].as_str().unwrap());
    let programs: Vec<Vec<u8>> = source["programs"].as_array().unwrap().iter().map(|p| hexv(&p["program_borsh_hex"])).collect();
    let of = &entry["offers"];
    let offers = PalwGenOffersV1 {
        steps: u32s(&of["steps"]),
        scalars: of["scalars"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| PalwGenScalarOfferV1 { lo: num(&x["lo"]) as i64, hi: num(&x["hi"]) as i64 })
            .collect(),
        max_prompt_tokens: of["max_prompt_tokens"].as_u64().unwrap() as u32,
        max_negative_tokens: of["max_negative_tokens"].as_u64().unwrap() as u32,
        images: of["images"]
            .as_array()
            .unwrap()
            .iter()
            .map(|i| PalwGenImageOfferV1 {
                h: i["h"].as_u64().unwrap() as u32,
                w: i["w"].as_u64().unwrap() as u32,
                tile_len: i["tile_len"].as_u64().unwrap() as u32,
                token_equivalents: i["token_equivalents"].as_u64().unwrap() as u32,
            })
            .collect(),
        max_source_tokens: of["max_source_tokens"].as_u64().unwrap() as u32,
        source_token_floor: of["source_token_floor"].as_u64().unwrap() as u32,
        forced_prompt_prefix: u32s(&of["forced_prompt_prefix"]),
        profile: profile_offers_of(&of["profile"]),
    };
    let out = &entry["output"];
    let class = PalwGenClassV1 {
        version: entry["version"].as_u64().unwrap() as u16,
        profile: entry["profile"].as_u64().unwrap() as u8,
        pipeline: hexv(&entry["pipeline_hex"]),
        programs,
        layouts: entry["layouts"].as_array().unwrap().iter().map(layout_of).collect(),
        output: OutputSpecV1 { kind: out["kind"].as_u64().unwrap() as u8, shape: u32s(&out["shape"]), meta: hexv(&out["meta_hex"]) },
        offers,
        tokenizer_id: Hash64::from_bytes(h64v(&entry["tokenizer_id_hex"])),
    };
    (class, Hash64::from_bytes(h64v(&entry["artifact_root_hex"])))
}

fn flip_last(h: &Hash64) -> Hash64 {
    let mut b: [u8; 64] = *h.as_byte_slice();
    b[63] ^= 1;
    Hash64::from_bytes(b)
}

/// The fifteen single-field changes of the file, by their stated words.
fn change(what: &str, class: &mut PalwGenClassV1, artifact_root: &mut Hash64) {
    match what {
        "artifact_root: the last byte ^ 1" => *artifact_root = flip_last(artifact_root),
        "tokenizer_id: the last byte ^ 1" => class.tokenizer_id = flip_last(&class.tokenizer_id),
        "version: 2" => class.version = 2,
        "profile: 2" => class.profile = 2,
        "pipeline: the byte at len / 2 ^ 1" => {
            let at = class.pipeline.len() / 2;
            class.pipeline[at] ^= 1;
        }
        "program 0's canonical bytes: the last byte ^ 1 (its graph_ir_root over those bytes)" => {
            let last = class.programs[0].len() - 1;
            class.programs[0][last] ^= 1;
        }
        "programs 0 and 1 swapped" => class.programs.swap(0, 1),
        "layouts[0].checkpoint_interval + 1" => class.layouts[0].checkpoint_interval += 1,
        "layouts[0].h_tile + 1" => class.layouts[0].h_tile += 1,
        "layouts 0 and 1 swapped" => class.layouts.swap(0, 1),
        "output.shape[0] + 1" => class.output.shape[0] += 1,
        "output.meta: one 0 byte appended" => class.output.meta.push(0),
        "offers.steps: one more step count appended" => {
            let next = class.offers.steps.last().copied().unwrap_or(0) + 1;
            class.offers.steps.push(next);
        }
        "offers.scalars[0].hi + 1" => class.offers.scalars[0].hi += 1,
        "offers.max_prompt_tokens + 1" => class.offers.max_prompt_tokens += 1,
        other => panic!("a single-field change this test does not know: {other}"),
    }
}

#[test]
fn the_class_id_vectors_hold_against_the_consensus_layer() {
    let v = load("tir-v2/class-id.json");
    let keys = &v["keys"];
    assert_eq!(
        keys["pipeline_root"].as_str().unwrap().as_bytes(),
        kaspa_consensus_core::palw_gen_class_v1::PALW_GEN_PIPELINE_ROOT_DOMAIN_V1
    );
    assert_eq!(
        keys["terms_digest"].as_str().unwrap().as_bytes(),
        kaspa_consensus_core::palw_gen_class_v1::PALW_GEN_CLASS_TERMS_DOMAIN_V1
    );
    assert_eq!(keys["class_id"].as_str().unwrap().as_bytes(), kaspa_consensus_core::palw_gen_class_v1::PALW_GEN_CLASS_ID_DOMAIN_V1);
    let classes = v["classes"].as_array().unwrap();
    assert_eq!(classes.len(), 8);
    let fence = PalwGenFenceV1::drill_v1(ForkActivation::always());
    let mut changes = 0;
    for entry in classes {
        let name = entry["name"].as_str().unwrap();
        let (class, root) = class_of(entry);
        // Every class is one the preflight admits.
        palw_gen_class_preflight_v1(&class, &fence).unwrap_or_else(|e| panic!("{name}: the class does not pass the preflight: {e}"));
        assert_eq!(class.pipeline_root().as_byte_slice(), &h64v(&entry["pipeline_root_hex"])[..], "{name}: pipeline_root");
        assert_eq!(class.terms_digest().as_byte_slice(), &h64v(&entry["terms_digest_hex"])[..], "{name}: terms_digest");
        assert_eq!(class.class_id(&root).as_byte_slice(), &h64v(&entry["class_id_hex"])[..], "{name}: class_id");
        // The borsh bytes the vector states are the consensus layer's.
        assert_eq!(borsh::to_vec(&class.layouts).unwrap(), hexv(&entry["layouts_borsh_hex"]), "{name}: layouts borsh");
        assert_eq!(borsh::to_vec(&class.output).unwrap(), hexv(&entry["output_borsh_hex"]), "{name}: output borsh");
        assert_eq!(borsh::to_vec(&class.offers).unwrap(), hexv(&entry["offers_borsh_hex"]), "{name}: offers borsh");
        // The programs' graph_ir_roots the pipeline root binds.
        for (k, program) in class.programs.iter().enumerate() {
            assert_eq!(
                kaspa_consensus_core::palw_tir_artifact_v1::palw_tir_graph_ir_root_v1(program).as_byte_slice(),
                &h64v(&entry["program_graph_ir_root_hex"][k])[..],
                "{name}: program {k}'s graph_ir_root"
            );
        }
        if let Some(rows) = entry["single_field_changes"].as_array() {
            assert_eq!(rows.len(), 15, "{name}: fifteen single-field changes");
            for row in rows {
                let what = row["change"].as_str().unwrap();
                let (mut c, mut r) = (class.clone(), root);
                change(what, &mut c, &mut r);
                assert_ne!(c.class_id(&r), class.class_id(&root), "{name}: {what} changes the id");
                assert_eq!(c.class_id(&r).as_byte_slice(), &h64v(&row["class_id_hex"])[..], "{name}: {what}");
                changes += 1;
            }
        }
    }
    assert_eq!(changes, 15);
}

